    if (instance->rootwin_opmenu_menu == NULL) {
        n = 0;
        XtSetArg(args[n], XmNrowColumnType, XmMENU_PULLDOWN);  ++n;
        instance->rootwin_opmenu_menu =
            XmCreatePulldownMenu(instance->group5,
                "rootwin_opmenu_menu", args, n);
    }
    if (instance->rootwin_opmenu_menu == NULL)
        return -1;

    if (instance->rootwin_opmenu == NULL) {
        n = 0;
        XtSetArg(args[n], XmNrowColumnType, XmMENU_OPTION);  ++n;
        XtSetArg(args[n], XmNspacing, 0);  ++n;
        XtSetArg(args[n], XmNpacking, XmPACK_TIGHT);  ++n;
        XtSetArg(args[n], XmNisHomogeneous, False);  ++n;
        XtSetArg(args[n], XmNsubMenuId, instance->rootwin_opmenu_menu);  ++n;
        instance->rootwin_opmenu =
            XmCreateOptionMenu(parent,
                "rootwin_opmenu", args, n);
    }
    if (instance->rootwin_opmenu == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 2, 36, "None                                          "));
